sp_widget.client_script:
/**
 * @name prompt_list (sp_widget)
 * @description Service Portal widget controller for listing Prompt records and creating new ones.
 *
 * Responsibilities:
 * - Render a list of `x_107457_test_prompt` records where `display_on_portal=true` (provided by the server script).
 * - Provide a "Create New" modal that collects only the Prompt text.
 * - Create a new record via a server call to this same widget and redirect to `prompt_record`.
 *
 * Navigation:
 * - On successful creation, redirects to `/sp?id=prompt_record&sys_id=<new_sys_id>`.
 *
 * Dependencies:
 * - `spUtil.get(widgetId, input)` for server calls
 * - `$window.location.href` for navigation
 */
api.controller = function($window, spUtil) {
  var c = this;

  c.getBadgeClass = function(index) {
    if (index === 0) return 'label label-primary';
    if (index === 1) return 'label label-success';
    if (index === 2) return 'label label-info';
    return 'label label-default';
  };

  c.showCreateModal = false;
  c.newPrompt = '';
  c.isCreating = false;
  c.errorMessage = '';

  c.openCreateModal = function() {
    c.errorMessage = '';
    c.newPrompt = '';
    c.showCreateModal = true;
  };

  c.closeCreateModal = function() {
    if (c.isCreating) return;
    c.showCreateModal = false;
  };

  c.createPrompt = function() {
    if (!c.newPrompt || c.isCreating) {
      return;
    }
    c.isCreating = true;
    c.errorMessage = '';

    spUtil.get('prompt_list', {
      action: 'create',
      prompt: c.newPrompt
    }).then(function(response) {
      if (response && response.data) {
        if (response.data.error) {
          c.errorMessage = response.data.error;
          return;
        }
        if (response.data.sys_id) {
          $window.location.href = '/sp?id=prompt_record&sys_id=' + response.data.sys_id;
        }
      }
    }).finally(function() {
      c.isCreating = false;
    });
  };
};

sp_widget.script:
/**
 * @name prompt_list (sp_widget) - Server script
 * @description Loads Prompt records for portal display and handles creation requests.
 *
 * Data contract:
 * - Output:
 *   - `data.records`: Array of records to render in the list (ordered by newest first).
 *   - `data.error`: Optional error message for create flow.
 *   - `data.sys_id`: Newly created sys_id when `input.action === 'create'`.
 * - Input:
 *   - `{ action: 'create', prompt: <string> }` to create a new prompt record.
 *
 * Side effects (create):
 * - Inserts a new record into `x_107457_test_prompt`
 * - Sets `prompt`, `user` (current logged-in user), and `display_on_portal=true`
 */
(function() {
  // Server script: load prompt records for portal or create new one
  data.records = data.records || [];

  // Handle create from client
  if (input && input.action === 'create') {
    var content = (input.prompt || '').toString();
    if (!content) {
      data.error = 'Prompt content is required.';
      return;
    }

    var createGr = new GlideRecord('x_107457_test_prompt');
    createGr.initialize();
    createGr.setValue('prompt', content);
    createGr.setValue('user', gs.getUserID());
    createGr.setValue('display_on_portal', true);
    var newSysId = createGr.insert();

    data.sys_id = newSysId;
    return;
  }

  // Default: list existing prompts
  var gr = new GlideRecord('x_107457_test_prompt');
  gr.addQuery('display_on_portal', true);
  gr.orderByDesc('sys_created_on');
  gr.query();

  while (gr.next()) {
    data.records.push({
      sys_id: gr.getUniqueValue(),
      created_on: gr.getDisplayValue('sys_created_on'),
      user: gr.getDisplayValue('user'),
      article: gr.getDisplayValue('article'),
      prompt: gr.getDisplayValue('prompt'),
      result: gr.getDisplayValue('result'),
      summary: gr.getDisplayValue('summary')
    });
  }
})();
